  "supportive_card_ids": ["C36", "C60", "C53", "C57"],
  "contradictory_card_ids": ["C04", "C02", "C07", "C13", "C08", "C11", "C16", "C20", "C23", "C33"],
  "prediction_basis_card_ids": ["C36", "C60"],
  "claims": [
    {
      "claim": "The query is an unPEGylated 4,5-epoxymorphinan with 6-keto and 14-hydroxy groups, structurally analogous to naloxone; C36 reports that naloxegol has better and more reproducible oral bioavailability than naloxone because glucuronidation is a minor clearance route for naloxegol, indicating that the unPEGylated scaffold has poor oral bioavailability.",
      "card_ids": ["C36"]
    },
    {
      "claim": "C60 reports pentazocine F = 0.18 ± 0.05 in healthy controls, below the 20% threshold, while F rises to 0.68 in cirrhosis; this provides affirmative low-F evidence for a related high-first-pass opioid and shows the high cirrhosis values are not transferable to a non-cirrhotic query.",
      "card_ids": ["C60", "C07", "C13"]
    },
    {
      "claim": "C04 reports codeine F = 80.5% in healthy subjects, but codeine lacks the 6-keto and 14-hydroxy groups that add first-pass metabolic liabilities in the query, so this high value is less transferable.",
      "card_ids": ["C04"]
    },
    {
      "claim": "C02 reports naloxegol F = 0.90 in a PBPK simulation, but C53 and C57 attribute naloxegol's oral bioavailability to PEGylation, which the query lacks.",
      "card_ids": ["C02", "C53", "C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
